    rows, cols = x.shape
    for i in range(0, rows, 128):
        r0 = i
        r1 = min(i + 128, rows)
        acc = np.full(r1 - r0, -np.inf)
        for j in range(0, cols, 512):
            c0 = j
            c1 = min(j + 512, cols)
            for c in range(c0, c1):
